    source:
      '//! Foundational allocation service used by higher standard-library actors.\n//!\n//! # When to use\n//! Provide [`Allocator`] to operations that may create owned storage, normally with\n//! [`SystemAllocator`].\n//!\n//! # Details\n//! [`Allocator`] is an ordinary source-declared service. Its requirement remains in an Effect\n//! until a caller supplies a provider, so tests and applications can replace the process-backed\n//! implementation lexically. Allocation failure is typed as [`OutOfMemoryError`].\n//!\n//! # Examples\n//! ## Provide the process allocator\n//! ```silk\n//! import silk.allocator { Allocator }\n//!\n//! import silk.bytes as Bytes\n//!\n//! import silk.effect { Effect }\n//!\n//! import silk.usize as usize\n//!\n//! effect fn copyMessage() -> i32\n//! ! Allocator.OutOfMemoryError {\n//!   let mut allocator = Allocator.systemAllocatorService()\n//!   let source = b"Silk"\n//!   let copying = Bytes.copy(&source)\n//!     |> Effect.provideMut<Allocator>(&mut allocator)\n//!   let bytes = run copying\n//!   return Bytes.length(&bytes)\n//!     |> usize.toI32\n//! }\n//!\n//! effect fn recoverAllocation(error: Allocator.OutOfMemoryError) -> i32 {\n//!   return 0\n//! }\n//!\n//! pub fn main() -> i32 {\n//!   return run Effect.catchAll(copyMessage(), recoverAllocation)\n//! }\n//! ```\n\nimport silk.layout { Layout as LayoutValue }\n\n/// A failure that reports that an allocator cannot satisfy a storage request.\npub struct OutOfMemoryError {}\n\n/// Fails immediately with `OutOfMemoryError`.\n///\n/// # When to use\n///\n/// Use this function to translate a checked size failure into the standard allocation failure.\npub effect fn outOfMemory() -> never ! OutOfMemoryError {\n  fail OutOfMemoryError {}\n}\n\n/// A mutable service that acquires owned storage described by a layout.\npub service Allocator {\n  /// Acquires one allocation for `layout`, or fails without returning partial storage.\n  effect fn allocate(layout: LayoutValue) -> Allocation ! OutOfMemoryError ? &mut Allocator\n}\n\n/// A process-backed provider for [`Allocator`].\npub struct SystemAllocator {}\n\n/// Creates a process-backed allocator provider without allocating storage.\npub fn systemAllocatorService() -> SystemAllocator {\n  return SystemAllocator {}\n}\n\neffect fn storageRefused(error: Intrinsic.StorageFailure) -> Allocation ! OutOfMemoryError {\n  drop error\n  fail OutOfMemoryError {}\n}\n\neffect fn rawSystemAllocate(\n  self: &mut SystemAllocator,\n  layout: LayoutValue\n) -> Allocation ! Intrinsic.StorageFailure {\n  return run Intrinsic.systemAllocationAcquire(move layout)\n}\n\neffect fn systemAllocate(self: &mut SystemAllocator, layout: LayoutValue) -> Allocation ! OutOfMemoryError {\n  return run Intrinsic.catchFailure<Intrinsic.StorageFailure>(\n    rawSystemAllocate(move self, move layout),\n    storageRefused\n  )\n}\n\nimpl Allocator for SystemAllocator {\n  allocate: SystemAllocator.systemAllocate\n}\n',
