    source:
      "//! One owned heap indirection for recursive data and values whose storage must have a stable size.\n//!\n//! # When to use\n//! Use [`Box`] to break an inline layout cycle, such as a tree node that owns more tree nodes. Use\n//! [`make`] to allocate, [`get`] or [`getMut`] to borrow the element, and [`into`] to recover it.\n//!\n//! # Details\n//! A box owns exactly one allocation and one value. Borrowing exposes a one-element slice because\n//! Silk can return a slice tied to a parameter but cannot return a bare borrowed value. Dropping\n//! the box recursively drops its element; consuming it with [`into`] transfers the element and\n//! still releases the allocation exactly once.\n//!\n//! # Gotchas\n//! Ordinary recursive destruction uses the call stack. For a very deep chain, consume links with\n//! [`into`] in an iterative loop when stack depth matters.\n//!\n//! # Examples\n//! ## Store and recover one owned value\n//! ```silk\n//! import silk.box as Box\n//!\n//! import silk.allocator { Allocator }\n//!\n//! import silk.effect { Effect }\n//!\n//! effect fn build() -> i32\n//! ! Allocator.OutOfMemoryError {\n//!   let mut allocator = Allocator.systemAllocatorService()\n//!   let creating = Box.make<i32>(42)\n//!     |> Effect.provideMut<Allocator>(&mut allocator)\n//!   let boxed = run creating\n//!   let borrowed = Box.get<i32>(&boxed)\n//!   if borrowed[0] != 42 {\n//!     return 1\n//!   }\n//!   return Box.into<i32>(move boxed)\n//! }\n//!\n//! effect fn recover(error: Allocator.OutOfMemoryError) -> i32 {\n//!   return 0\n//! }\n//!\n//! pub fn main() -> i32 {\n//!   return run Effect.catchAll(build(), recover)\n//! }\n//! ```\n\n// One owned heap indirection holding exactly one value. Ordinary Silk: no compiler phase knows\n// this type, and every capability it uses is available to user code.\n//\n// A struct may reach itself through a Box because RawBuffer's representation is the same whatever\n// it holds, so the holder's layout never needs the held type's layout. The same fact is why the\n// Drop hook below has work to do: releasing a RawBuffer releases the block without descending into\n// the element, so a box that did not drop its own element would abandon every level beneath it.\n//\n// The occupancy marker is what lets the hook and `into` agree. `into` hands the value out and\n// marks the box vacant, so the hook that still runs when the emptied box leaves scope drops\n// nothing, and the buffer releases exactly once either way. The marker is deliberately not generic\n// over T: a `[T; 0]` anchor of the kind Vector uses would be an inline reach into T and would make\n// a struct holding `Box` of itself recursive again.\n\nimport silk.allocator { Allocator }\nimport silk.allocator { OutOfMemoryError }\nimport silk.layout { Layout }\nimport silk.raw_buffer as RawBuffer\nimport silk.slot as Slot\nimport silk.usize as usize\n\n/// A marker for a box whose element has been transferred to its caller.\npub struct Vacant {}\n\n/// A marker for a box that owns one initialized element.\npub struct Occupied {}\n\n/// Owns one heap-allocated `T` and releases both the value and its allocation on drop.\npub struct Box<T> {\n  buffer: RawBuffer<T>\n  state: Vacant | Occupied\n}\n\n// Diverges on the arms the surrounding logic has already proven impossible.\nfn absurd<T>() -> T {\n  let boom = 1 / 0\n  return absurd<T>()\n}\n\n/// Moves one value into a new box with storage for exactly one element.\n///\n/// # Details\n///\n/// The returned box owns the value and the allocation. Allocation failure produces\n/// `OutOfMemoryError` and does not produce a partial box.\npub effect fn make<T>(value: T) -> Box<T> ! OutOfMemoryError ? &mut Allocator {\n  let layout = Layout.of<T>()\n  let recipe = Allocator.allocate(move layout)\n  let allocation = run recipe\n  let buffer = freshBuffer<T>(move allocation)\n  return Box<T> { buffer: writeFirst<T>(move buffer, move value), state: Occupied {} }\n}\n\nfn freshBuffer<T>(allocation: Allocation) -> RawBuffer<T> {\n  unsafe {\n    let made = RawBuffer.from<T>(move allocation, usize.ONE)\n    return move made\n  }\n  return absurd<RawBuffer<T>>()\n}\n\nfn writeFirst<T>(buffer: RawBuffer<T>, value: T) -> RawBuffer<T> {\n  unsafe {\n    let mut owned = move buffer\n    let selected = RawBuffer.slot<T>(&mut owned, usize.ZERO)\n    let written = Slot.write<T>(move selected, move value)\n    return move owned\n  }\n  return absurd<RawBuffer<T>>()\n}\n\n// The held value is borrowed as a one-element view rather than as a bare reference: a function\n// may return a lexical slice borrowed from one parameter, and no Silk function may return `&T`.\n/// Borrows the held value as a shared slice of length one.\n///\n/// # Details\n///\n/// The slice borrows the box and remains valid only for the lexical borrow.\npub fn get<T>(self: &Box<T>) -> &[T] {\n  return RawBuffer.view<T>(&self.buffer, usize.ZERO, usize.ONE)\n}\n\n/// Borrows the held value as an exclusive slice of length one.\n///\n/// # Details\n///\n/// The slice permits mutation of the element and remains valid only for the lexical borrow.\npub fn getMut<T>(self: &mut Box<T>) -> &mut [T] {\n  return RawBuffer.viewMut<T>(&mut self.buffer, usize.ZERO, usize.ONE)\n}\n\n// Marking the box vacant first is what keeps the value from being dropped twice: the box still\n// runs its hook when this scope ends, and by then it holds nothing to drop.\n/// Consumes the box, returns its owned value, and releases its allocation.\npub fn into<T>(self: Box<T>) -> T {\n  let mut owned = move self\n  let state = Intrinsic.replace(owned.state, Vacant {})\n  return match move state {\n    Vacant nothing => absurd<T>()\n    Occupied held => takeElement<T>(&mut owned.buffer)\n  }\n}\n\nfn takeElement<T>(buffer: &mut RawBuffer<T>) -> T {\n  unsafe {\n    let selected = RawBuffer.slot<T>(move buffer, usize.ZERO)\n    return Slot.take<T>(move selected)\n  }\n  return absurd<T>()\n}\n\n// The hook drops the element only. The buffer belongs to the field cleanup the plan runs straight\n// after this returns, so the storage releases exactly once whichever way the box was emptied.\nimpl<T> Drop for Box<T> {\n  fn drop(self: &mut Box<T>) -> () {\n    let state = Intrinsic.replace(self.state, Vacant {})\n    return match move state {\n      Vacant nothing => ()\n      Occupied held => dropElement<T>(&mut self.buffer)\n    }\n  }\n}\n\nfn dropElement<T>(buffer: &mut RawBuffer<T>) -> () {\n  unsafe {\n    let selected = RawBuffer.slot<T>(move buffer, usize.ZERO)\n    let cleared = Slot.dropValue<T>(move selected)\n  }\n  return ()\n}\n",
