    source:
      '//! Owned arbitrary bytes for file contents, process output, and other encoding-neutral data.\n//!\n//! # When to use\n//! Use [`Bytes`] when every octet must round-trip unchanged. Use `silk.string.String` instead when\n//! the value is known to be valid UTF-8 and callers need text operations.\n//!\n//! # Details\n//! [`make`] creates an empty value without allocating, while [`zeroed`], [`copy`], and [`append`]\n//! may require an [`Allocator`]. Shared and exclusive views borrow only the initialized prefix;\n//! later appends can reallocate, so do not retain a view across a mutation.\n//!\n//! # Examples\n//! ## Copy, append, and update bytes\n//! ```silk\n//! import silk.bytes as Bytes\n//!\n//! import silk.allocator { Allocator }\n//!\n//! import silk.effect { Effect }\n//!\n//! import silk.u8 as u8\n//!\n//! effect fn build() -> i32\n//! ! Allocator.OutOfMemoryError {\n//!   let mut allocator = Allocator.systemAllocatorService()\n//!   let source = b"AB"\n//!   let copying = Bytes.copy(&source)\n//!     |> Effect.provideMut<Allocator>(&mut allocator)\n//!   let mut bytes = run copying\n//!   let suffix = b"C"\n//!   let appending = Bytes.append(&mut bytes, &suffix)\n//!     |> Effect.provideMut<Allocator>(&mut allocator)\n//!   let appended = run appending\n//!   let mut writable = Bytes.asMutSlice(&mut bytes)\n//!   writable[1] = u8.toU8(48)\n//!   let readable = Bytes.asSlice(&bytes)\n//!   return u8.toI32(readable[0]) - u8.toI32(readable[1]) + u8.toI32(readable[2]) - 42\n//! }\n//!\n//! effect fn recover(error: Allocator.OutOfMemoryError) -> i32 {\n//!   return 0\n//! }\n//!\n//! pub fn main() -> i32 {\n//!   return run Effect.catchAll(build(), recover)\n//! }\n//! ```\n\nimport silk.allocator { Allocator }\nimport silk.allocator { OutOfMemoryError }\nimport silk.u8 as u8\nimport silk.usize as usize\nimport silk.vector {\n  Vector,\n  make as vectorMake,\n  append as vectorAppend,\n  appendBytes as vectorAppendBytes,\n  length as vectorLength,\n  asSlice as vectorAsSlice,\n  asMutSlice as vectorAsMutSlice\n}\n\n/// An owned encoding-neutral sequence of arbitrary octets.\n///\n/// # Details\n///\n/// A value owns its initialized bytes and releases their storage on drop. Its length can grow with\n/// [`append`], and its capacity is not part of the public contract.\npub struct Bytes {\n  values: Vector<u8>\n}\n\n/// Creates an empty `Bytes` value without allocating storage.\npub fn make() -> Bytes {\n  return Bytes { values: vectorMake<u8>() }\n}\n\n/// Allocates an owned initialized byte buffer of exactly `length` zero octets.\n///\n/// # Details\n///\n/// A zero length returns an empty value without an allocation.\npub effect fn zeroed(length: usize) -> Bytes ! OutOfMemoryError ? &mut Allocator {\n  let mut result = make()\n  let mut index = usize.ZERO\n  while index < length {\n    let appended = run vectorAppend<u8>(&mut result.values, u8.toU8(0))\n    index = index + usize.ONE\n  }\n  return move result\n}\n\n/// Returns the initialized byte count.\npub fn length(self: &Bytes) -> usize {\n  return vectorLength<u8>(&self.values)\n}\n\n/// Copies a complete borrowed byte sequence into independently owned storage.\npub effect fn copy(values: &[u8]) -> Bytes ! OutOfMemoryError ? &mut Allocator {\n  let mut result = make()\n  let appended = run append(&mut result, values)\n  return move result\n}\n\n/// Appends a complete borrowed byte sequence in source order.\n///\n/// # Details\n///\n/// If growth fails, the original bytes and their length remain unchanged.\npub effect fn append(self: &mut Bytes, values: &[u8]) -> () ! OutOfMemoryError ? &mut Allocator {\n  let appended = run vectorAppendBytes(&mut self.values, values)\n  return ()\n}\n\n/// Borrows all initialized octets as one shared lexical slice.\npub fn asSlice(self: &Bytes) -> &[u8] {\n  return vectorAsSlice<u8>(&self.values)\n}\n\n/// Borrows all initialized octets as one exclusive lexical slice.\n///\n/// # Gotchas\n///\n/// Do not retain this slice across [`append`], because an append can replace the allocation.\npub fn asMutSlice(self: &mut Bytes) -> &mut [u8] {\n  return vectorAsMutSlice<u8>(&mut self.values)\n}\n',
