    namespace: 'char',
    source:
      "//! Checked construction, integer inspection, equality, and ordering for Unicode scalar `char`\n//! values.\n//!\n//! # When to use\n//! Prefer comparison operators in direct expressions. Import these functions when comparison must\n//! be passed by name or when the Unicode scalar ordering should be explicit at a call site.\n//!\n//! # Details\n//! Ordering compares scalar values, not locale collation, normalization, grapheme clusters, or UTF-8\n//! byte sequences. These functions allocate no storage and add no Effect channels.\n//!\n//! # Gotchas\n//! Integer construction rejects `0xD800` through `0xDFFF` and values above `0x10FFFF`. It returns\n//! `None`; it does not truncate or trap.\n//!\n//! # Examples\n//! ## Validate a Unicode scalar integer\n//! ```silk\n//! import silk.char as Char\n//!\n//! import silk.option as Option\n//!\n//! pub fn main() -> i32 {\n//!   let scalar = Char.fromU32(0x2603)\n//!   let value = move scalar\n//!     |> Option.unwrapOr<char>('?')\n//!   if Char.toU32(value) != 0x2603 {\n//!     return 1\n//!   }\n//!   let surrogate = Char.fromU32(0xD800)\n//!   let replacement = move surrogate\n//!     |> Option.unwrapOr<char>('?')\n//!   if replacement != '?' {\n//!     return 2\n//!   }\n//!   return 42\n//! }\n//! ```\n\nimport silk.bool as bool\nimport silk.option { Option }\nimport silk.u32 as u32\n\n/// Converts an integer to a Unicode scalar. Returns `None` for `0xD800` through `0xDFFF` and values\n/// above `0x10FFFF`.\npub fn fromU32(value: u32) -> Option<char> {\n  return Intrinsic.charFromU32(value)\n}\n\n/// Returns the exact integer value of an already valid Unicode scalar.\npub fn toU32(value: char) -> u32 {\n  return Intrinsic.charToU32(value)\n}\n\n/// Returns `true` when `left` and `right` are the same Unicode scalar value.\npub fn equals(left: char, right: char) -> bool {\n  return Intrinsic.charEquals(left, right)\n}\n\n/// Returns `true` when `left` and `right` are different Unicode scalar values.\npub fn notEquals(left: char, right: char) -> bool {\n  return Intrinsic.charNotEquals(left, right)\n}\n\n/// Returns `true` when the Unicode scalar value of `left` is less than `right`.\npub fn lessThan(left: char, right: char) -> bool {\n  return Intrinsic.charLessThan(&left, &right)\n}\n\n/// Returns `true` when the Unicode scalar value of `left` is less than or equal to `right`.\npub fn lessOrEqual(left: char, right: char) -> bool {\n  return Intrinsic.charLessOrEqual(left, right)\n}\n\n/// Returns `true` when the Unicode scalar value of `left` is greater than `right`.\npub fn greaterThan(left: char, right: char) -> bool {\n  return Intrinsic.charGreaterThan(left, right)\n}\n\n/// Returns `true` when the Unicode scalar value of `left` is greater than or equal to `right`.\npub fn greaterOrEqual(left: char, right: char) -> bool {\n  return Intrinsic.charGreaterOrEqual(left, right)\n}\n",
