    source:
      "//! Compile-time ordering witnesses and a three-way result derived from strict comparison.\n//!\n//! # When to use\n//! Add an [`Order`] bound when a generic algorithm needs `<`, as sorting and binary search do. Use\n//! [`compare`] when all three outcomes matter, or [`less`] and [`equal`] for predicates.\n//!\n//! # Details\n//! An interface witness is selected during specialization; it creates no service requirement or\n//! runtime dispatch. [`Equal`] means neither operand orders before the other, so equality cannot\n//! disagree with the witness's own strict ordering.\n//!\n//! # Gotchas\n//! A witness must define a strict total order. The module cannot verify this law. If two different\n//! values are incomparable, [`compare`] and [`equal`] report them as equal.\n//!\n//! # Examples\n//! ## Classify each comparison result\n//! ```silk\n//! import silk.order as Order\n//!\n//! pub fn main() -> i32 {\n//!   let low = Order.compare<i32>(2, 7)\n//!   let same = Order.compare<i32>(7, 7)\n//!   let high = Order.compare<i32>(9, 7)\n//!   if !Order.isLess(&low) {\n//!     return 1\n//!   }\n//!   if !Order.isEqual(&same) {\n//!     return 2\n//!   }\n//!   if !Order.isGreater(&high) {\n//!     return 3\n//!   }\n//!   return 42\n//! }\n//! ```\n\n// The comparison contract the ordered sequence operations resolve against. Ordinary Silk: the\n// interface selects a compiler-known comparison during specialization exactly as `Integer` does, and\n// creates no effect requirement, provider slot, or runtime dispatch.\n//\n// The contract is `lessThan` rather than a three-way `compare` because an interface operation is\n// reachable from a generic body only through the operator that spells it. `<` spells `lessThan`, so\n// a body bounded by `Order` can compare; no operator spells `compare`, so a `compare` operation\n// would be declared and mapped yet uncallable. The three-way result is derived here instead, from\n// the two strict comparisons, and is therefore ordinary Silk over the same one-operation bound.\n\nimport silk.bool as bool\nimport silk.i16 as i16\nimport silk.i32 as i32\nimport silk.i64 as i64\nimport silk.i8 as i8\nimport silk.isize as isize\nimport silk.u16 as u16\nimport silk.u32 as u32\nimport silk.u64 as u64\nimport silk.u8 as u8\nimport silk.usize as usize\n\n/// The left value orders before the right value.\npub struct Less {}\n\n/// Neither value orders before the other.\npub struct Equal {}\n\n/// The left value orders after the right value.\npub struct Greater {}\n\n/// A three-way comparison result that contains exactly one of [`Less`], [`Equal`], or [`Greater`].\npub struct Ordering {\n  /// The comparison result, which a `match` expression narrows to one outcome type.\n  pub value: Less | Equal | Greater\n}\n\n/// Static strict-ordering contract for primitive comparable values.\n///\n/// # When to use\n///\n/// Use this interface when a generic algorithm needs strict ordering through `<`.\n///\n/// # Details\n///\n/// A witness supplies the strict `lessThan` the operator `<` spells. Equality is derived from it\n/// rather than declared, so a witness cannot disagree with itself about which values are equal.\n///\n/// # Gotchas\n///\n/// An implementation must define a strict total order. If two different values are incomparable,\n/// [`compare`] and [`equal`] treat them as equal.\npub interface Order {\n  /// Reports whether `left` orders strictly before `right`. An implementation must define a strict\n  /// total order so different values are not incomparable.\n  operator < fn lessThan(left: &Self, right: &Self) -> bool\n}\n\nimpl Order for u8 { lessThan: Intrinsic.u8LessThan }\nimpl Order for u16 { lessThan: Intrinsic.u16LessThan }\nimpl Order for u32 { lessThan: Intrinsic.u32LessThan }\nimpl Order for u64 { lessThan: Intrinsic.u64LessThan }\nimpl Order for usize { lessThan: Intrinsic.usizeLessThan }\nimpl Order for i8 { lessThan: Intrinsic.i8LessThan }\nimpl Order for i16 { lessThan: Intrinsic.i16LessThan }\nimpl Order for i32 { lessThan: Intrinsic.i32LessThan }\nimpl Order for i64 { lessThan: Intrinsic.i64LessThan }\nimpl Order for isize { lessThan: Intrinsic.isizeLessThan }\n\n/// Compares two values three ways using the concrete comparison selected during specialization.\n///\n/// # When to use\n///\n/// Use this function when the caller needs to distinguish less, equal, and greater outcomes.\n///\n/// # Details\n///\n/// Calls the selected strict comparison with `left, right`. If that result is false, it calls the\n/// comparison with `right, left`. The function then consumes both owned arguments.\n///\n/// # Gotchas\n///\n/// If neither comparison is true, this function returns [`Equal`]. The witness must not leave two\n/// different values incomparable.\npub fn compare<T: Order>(left: T, right: T) -> Ordering {\n  if (&left) < (&right) {\n    return Ordering { value: Less {} }\n  }\n  if (&right) < (&left) {\n    return Ordering { value: Greater {} }\n  }\n  return Ordering { value: Equal {} }\n}\n\n/// Reports whether `left` orders strictly before `right` under the selected [`Order`] witness. The\n/// function calls the witness once and then consumes both owned arguments.\npub fn less<T: Order>(left: T, right: T) -> bool {\n  return (&left) < (&right)\n}\n\n/// Reports whether neither value orders before the other under the selected [`Order`] witness. The\n/// function calls the witness once or twice and then consumes both owned arguments.\n///\n/// # Gotchas\n///\n/// If the witness leaves different values incomparable, this function reports them as equal.\npub fn equal<T: Order>(left: T, right: T) -> bool {\n  if (&left) < (&right) {\n    return false\n  }\n  return !((&right) < (&left))\n}\n\n/// Reports whether an ordering is `Less`.\npub fn isLess(ordering: &Ordering) -> bool {\n  return match &ordering.value {\n    Less {} => true\n    Equal {} => false\n    Greater {} => false\n  }\n}\n\n/// Reports whether an ordering is `Equal`.\npub fn isEqual(ordering: &Ordering) -> bool {\n  return match &ordering.value {\n    Less {} => false\n    Equal {} => true\n    Greater {} => false\n  }\n}\n\n/// Reports whether an ordering is `Greater`.\npub fn isGreater(ordering: &Ordering) -> bool {\n  return match &ordering.value {\n    Less {} => false\n    Equal {} => false\n    Greater {} => true\n  }\n}\n",
