      "//! Native [`StandardInput`] provider backed by the process standard-input descriptor.\n//!\n//! # When to use\n//! Construct [`OsStandardInput`] at a native application edge and provide it to portable byte-input\n//! code. Use a scripted provider in tests to control partial reads, end-of-input, and failures.\n//!\n//! # Details\n//! The provider owns no persistent state and commits each host read directly into the caller's\n//! buffer. For a non-empty buffer, a zero-length host transfer becomes the outcome selected by\n//! [`endOfInput`]. Only a host read error becomes [`StreamReadError`]. Partial transfer counts are\n//! preserved exactly.\n//!\n//! Constructing the provider performs no read. Portable code reads after the application supplies\n//! `&mut OsStandardInput` for the `&mut StandardInput` requirement.\n//!\n//! # Gotchas\n//! Reachable OS standard-input operations are native-only. Direct WebAssembly compilation rejects\n//! them instead of inventing a descriptor import. Evaluator execution requires an injected adapter.\n//! The caller must use a non-empty buffer. A zero-capacity host read also transfers zero bytes.\n//!\n//! # Examples\n//! ## Construct the native provider without reading standard input\n//!\n//! ```silk\n//! import silk.os_standard_input as OsStandardInput\n//!\n//! pub fn main() -> i32 {\n//!   let provider = OsStandardInput.make()\n//!   drop provider\n//!   return 42\n//! }\n//! ```\n\nimport silk.i32 as i32\nimport silk.option { None, Option, Some, none }\nimport silk.standard_input {\n  ReadOutcome,\n  StandardInput,\n  StreamReadError,\n  endOfInput,\n  filled,\n  readFailure\n}\nimport silk.u32 as u32\nimport silk.u8 as u8\nimport silk.usize as usize\n\n/// A stateless native [`StandardInput`] provider for the process input descriptor.\n///\n/// # Details\n///\n/// The process owns the descriptor. Each read changes only the committed prefix of the caller's\n/// buffer and preserves the host transfer count.\npub struct OsStandardInput {}\n\n/// Creates a stateless provider for native standard-input bytes.\n///\n/// # When to use\n///\n/// Use this function at a native application edge. Provide the result as `&mut StandardInput` to\n/// portable code that calls `silk.standard_input.receive`.\n///\n/// # Details\n///\n/// Construction performs no read and cannot fail. For a non-empty read buffer, a later zero-byte\n/// host transfer becomes end-of-input data. A host read error becomes [`StreamReadError`].\npub fn make() -> OsStandardInput {\n  return OsStandardInput {}\n}\n\neffect fn rawRead(output: &mut [u8], lowReason: &mut i32, nativeCode: &mut u32) -> Option<usize> {\n  unsafe { return run Intrinsic.osStandardInputRead(output, lowReason, nativeCode) }\n  let impossible = 1 / 0\n  return none<usize>()\n}\n\neffect fn raise() -> never ! StreamReadError {\n  fail readFailure()\n}\n\n/// Commits one host read into the caller's buffer.\n///\n/// The low-level boundary reports a zero-length transfer for the end of input, which becomes\n/// `EndOfInput` data rather than a typed failure. Only a host error becomes `StreamReadError`.\n///\n/// The caller must use a non-empty `buffer`. With no capacity, the host also reports a zero-length\n/// transfer and cannot prove permanent end-of-input.\neffect fn read(self: &mut OsStandardInput, buffer: &mut [u8]) -> ReadOutcome ! StreamReadError {\n  let mut lowReason = 0\n  let mut nativeCode = u32.toU32(0)\n  let received = run rawRead(move buffer, &mut lowReason, &mut nativeCode)\n  let length = match move received {\n    None {} => run raise()\n    Some<usize> { value: selected } => selected\n  }\n  if length == usize.ZERO { return endOfInput() }\n  return filled(length)\n}\n\nimpl StandardInput for OsStandardInput {\n  read: OsStandardInput.read\n}\n",
